// The competitive formats (gens 4 to 9) and helpers around them. Pure: tested in legality.test.mjs.
// Which species each format allows is generated by scripts/build-formats.mjs (Showdown's validator)
// into src/data/formats/<id>.json. Adventure availability comes from lib/availability.ts instead.
// Relative with .ts so node --test can load it too.
import { FORMATS } from "../data/formats/index.ts";

export type TeamMode = "smogon" | "vgc" | "adventure";
export type CompetitiveMode = Exclude<TeamMode, "adventure">;
export type FormatInfo = (typeof FORMATS)[number];

export { FORMATS };

// Newest first, as the "New team" dialog lists them.
export const GENS = [9, 8, 7, 6, 5, 4] as const;

export const formatInfo = (id: string): FormatInfo | undefined => FORMATS.find((f) => f.id === id);

// Format ids follow Showdown's ("gen6ou", "gen9vgc2026regf"): the generation is the digit after "gen".
export const formatGen = (id: string): number =>
  formatInfo(id)?.gen ?? Number(id.match(/^gen(\d)/)?.[1] ?? 9);

export const competitiveFormats = (mode: CompetitiveMode, gen: number): string[] =>
  FORMATS.filter((f) => f.mode === mode && f.gen === gen).map((f) => f.id);

// Generations that have at least one format in this mode (no VGC in gen 4).
export const gensOf = (mode: CompetitiveMode): number[] =>
  GENS.filter((gen) => competitiveFormats(mode, gen).length > 0);

// Smogon singles tiers, strongest first.
const SMOGON_ORDER = [
  "AG",
  "Uber",
  "OU",
  "UUBL",
  "UU",
  "RUBL",
  "RU",
  "NUBL",
  "NU",
  "PUBL",
  "PU",
  "ZUBL",
  "ZU",
  "NFE",
  "LC",
];

// The tier filter's chips: the Smogon tiers found among a format's legal species, strongest first.
export function tiersAmong(tiers: Iterable<string | undefined>): string[] {
  const present = new Set(tiers);
  return SMOGON_ORDER.filter((t) => present.has(t));
}
